if (!customElements.get('product-form')) {
  customElements.define(
    'product-form',
    class ProductForm extends HTMLElement {
      constructor() {
        super();

        this.form = this.querySelector('form');
        this.variantIdInput.disabled = false;
        this.form.addEventListener('submit', this.onSubmitHandler.bind(this));
        this.cart = document.querySelector('cart-notification') || document.querySelector('cart-drawer');
        this.submitButton = this.querySelector('[type="submit"]');
        this.submitButtonText = this.submitButton.querySelector('span');

        if (document.querySelector('cart-drawer')) this.submitButton.setAttribute('aria-haspopup', 'dialog');

        this.hideErrors = this.dataset.hideErrors === 'true';
      }

      onSubmitHandler(evt) {
        evt.preventDefault();
        if (this.submitButton.getAttribute('aria-disabled') === 'true') return;

        this.handleErrorMessage();

        this.submitButton.setAttribute('aria-disabled', true);
        this.submitButton.classList.add('loading');
        this.querySelector('.loading__spinner').classList.remove('hidden');

        const config = fetchConfig('javascript');
        config.headers['X-Requested-With'] = 'XMLHttpRequest';
        delete config.headers['Content-Type'];

        const formData = new FormData(this.form);
        if (this.cart) {
          formData.append(
            'sections',
            this.cart.getSectionsToRender().map((section) => section.id)
          );
          formData.append('sections_url', window.location.pathname);
          this.cart.setActiveElement(document.activeElement);
        }
        config.body = formData;

        const variantId = formData.get('id');
        const quantity = parseInt(formData.get('quantity')) || 1;
        const linesUpdateDeferred = this.createCartLinesUpdateEvent(variantId, quantity);

        fetch(`${routes.cart_add_url}`, config)
          .then((response) => response.json())
          .then((response) => {
            if (response.status) {
              publish(PUB_SUB_EVENTS.cartError, {
                source: 'product-form',
                productVariantId: variantId,
                errors: response.errors || response.description,
                message: response.message,
              });
              this.handleErrorMessage(response.description);
              this.dispatchCartErrorEvent(response.description || response.message, 'INVALID');
              linesUpdateDeferred?.reject(new Error(response.description || response.message));

              const soldOutMessage = this.submitButton.querySelector('.sold-out-message');
              if (!soldOutMessage) return;
              this.submitButton.setAttribute('aria-disabled', true);
              this.submitButtonText.classList.add('hidden');
              soldOutMessage.classList.remove('hidden');
              this.error = true;
              return;
            } else if (!this.cart) {
              this.resolveCartLinesUpdate(linesUpdateDeferred);
              window.location = window.routes.cart_url;
              return;
            }

            this.resolveCartLinesUpdate(linesUpdateDeferred);

            const startMarker = CartPerformance.createStartingMarker('add:wait-for-subscribers');
            if (!this.error)
              publish(PUB_SUB_EVENTS.cartUpdate, {
                source: 'product-form',
                productVariantId: variantId,
                cartData: response,
              }).then(() => {
                CartPerformance.measureFromMarker('add:wait-for-subscribers', startMarker);
              });
            this.error = false;
            const quickAddModal = this.closest('quick-add-modal');
            if (quickAddModal) {
              document.body.addEventListener(
                'modalClosed',
                () => {
                  setTimeout(() => {
                    CartPerformance.measure("add:paint-updated-sections", () => {
                      this.cart.renderContents(response);
                    });
                  });
                },
                { once: true }
              );
              quickAddModal.hide(true);
            } else {
              CartPerformance.measure("add:paint-updated-sections", () => {
                this.cart.renderContents(response);
              });
            }
          })
          .catch((e) => {
            console.error(e);
            this.dispatchCartErrorEvent(e.message || 'Network error', 'SERVICE_UNAVAILABLE');
            linesUpdateDeferred?.reject(e);
          })
          .finally(() => {
            this.submitButton.classList.remove('loading');
            if (this.cart && this.cart.classList.contains('is-empty')) this.cart.classList.remove('is-empty');
            if (!this.error) this.submitButton.removeAttribute('aria-disabled');
            this.querySelector('.loading__spinner').classList.add('hidden');

            CartPerformance.measureFromEvent("add:user-action", evt);
          });
      }

      handleErrorMessage(errorMessage = false) {
        if (this.hideErrors) return;

        this.errorMessageWrapper =
          this.errorMessageWrapper || this.querySelector('.product-form__error-message-wrapper');
        if (!this.errorMessageWrapper) return;
        this.errorMessage = this.errorMessage || this.errorMessageWrapper.querySelector('.product-form__error-message');

        this.errorMessageWrapper.toggleAttribute('hidden', !errorMessage);

        if (errorMessage) {
          this.errorMessage.textContent = errorMessage;
        }
      }

      toggleSubmitButton(disable = true, text) {
        if (disable) {
          this.submitButton.setAttribute('disabled', 'disabled');
          if (text) this.submitButtonText.textContent = text;
        } else {
          this.submitButton.removeAttribute('disabled');
          this.submitButtonText.textContent = window.variantStrings.addToCart;
        }
      }

      createCartLinesUpdateEvent(variantId, quantity) {
        const { CartLinesUpdateEvent } = window.StandardEvents || {};
        if (!CartLinesUpdateEvent) return null;

        const deferred = CartLinesUpdateEvent.createPromise();
        this.dispatchEvent(
          new CartLinesUpdateEvent({
            action: 'add',
            context: 'product',
            lines: [{ merchandiseId: variantId, quantity }],
            promise: deferred.promise,
          })
        );
        return deferred;
      }

      resolveCartLinesUpdate(deferred) {
        if (!deferred) return;
        const { CartLinesUpdateEvent } = window.StandardEvents || {};
        if (!CartLinesUpdateEvent) return;

        const pendingCartDataPromise = typeof CartItems !== 'undefined'
          ? CartItems.fetchCartData()
          : fetch(`${routes.cart_url}.json`).then((response) => response.json());

        pendingCartDataPromise
          .then((cart) => {
            if (!cart?.currency) return deferred.reject(new Error('Missing currency in cart response'));
            deferred.resolve({ cart: CartLinesUpdateEvent.createCartFromAjaxResponse(cart) });
          })
          .catch((e) => deferred.reject(e));
      }

      dispatchCartErrorEvent(message, code) {
        const { CartErrorEvent } = window.StandardEvents || {};
        if (!CartErrorEvent) return;
        this.dispatchEvent(new CartErrorEvent({ error: message, code }));
      }

      get variantIdInput() {
        return this.form.querySelector('[name=id]');
      }
    }
  );
}

if (!customElements.get('product-info')) {
  customElements.define(
    'product-info',
    class ProductInfo extends HTMLElement {
      quantityInput = undefined;
      quantityForm = undefined;
      onVariantChangeUnsubscriber = undefined;
      cartUpdateUnsubscriber = undefined;
      abortController = undefined;
      pendingRequestUrl = null;
      preProcessHtmlCallbacks = [];
      postProcessHtmlCallbacks = [];

      constructor() {
        super();

        this.quantityInput = this.querySelector('.quantity__input');
      }

      connectedCallback() {
        this.initializeProductSwapUtility();

        this.onVariantChangeUnsubscriber = subscribe(
          PUB_SUB_EVENTS.optionValueSelectionChange,
          this.handleOptionValueChange.bind(this)
        );

        this.initQuantityHandlers();
        this.dispatchEvent(new CustomEvent('product-info:loaded', { bubbles: true }));
      }

      addPreProcessCallback(callback) {
        this.preProcessHtmlCallbacks.push(callback);
      }

      initQuantityHandlers() {
        if (!this.quantityInput) return;

        this.quantityForm = this.querySelector('.product-form__quantity');
        if (!this.quantityForm) return;

        this.setQuantityBoundries();
        if (!this.dataset.originalSection) {
          this.cartUpdateUnsubscriber = subscribe(PUB_SUB_EVENTS.cartUpdate, this.fetchQuantityRules.bind(this));
        }
      }

      disconnectedCallback() {
        this.onVariantChangeUnsubscriber();
        this.cartUpdateUnsubscriber?.();
      }

      initializeProductSwapUtility() {
        this.preProcessHtmlCallbacks.push((html) =>
          html.querySelectorAll('.scroll-trigger').forEach((element) => element.classList.add('scroll-trigger--cancel'))
        );
        this.postProcessHtmlCallbacks.push((newNode) => {
          window?.Shopify?.PaymentButton?.init();
          window?.ProductModel?.loadShopifyXR();
        });
      }

      handleOptionValueChange({ data: { event, target, selectedOptionValues } }) {
        if (!this.contains(event.target)) return;

        this.resetProductFormState();

        const productUrl = target.dataset.productUrl || this.pendingRequestUrl || this.dataset.url;
        this.pendingRequestUrl = productUrl;
        const shouldSwapProduct = this.dataset.url !== productUrl;
        const shouldFetchFullPage = this.dataset.updateUrl === 'true' && shouldSwapProduct;

        this.renderProductInfo({
          requestUrl: this.buildRequestUrlWithParams(productUrl, selectedOptionValues, shouldFetchFullPage),
          targetId: target.id,
          callback: shouldSwapProduct
            ? this.handleSwapProduct(productUrl, shouldFetchFullPage)
            : this.handleUpdateProductInfo(productUrl),
        });
      }

      resetProductFormState() {
        const productForm = this.productForm;
        productForm?.toggleSubmitButton(true);
        productForm?.handleErrorMessage();
      }

      handleSwapProduct(productUrl, updateFullPage) {
        return (html) => {
          this.productModal?.remove();

          const selector = updateFullPage ? "product-info[id^='MainProduct']" : 'product-info';
          const sourceProductInfo = html.querySelector(selector);
          const variant = this.getSelectedVariant(sourceProductInfo);
          this.variantSelectors?.resolvePendingSelectPromise(variant, this.getVariantSelects(sourceProductInfo));
          this.updateURL(productUrl, variant?.id);

          if (updateFullPage) {
            document.querySelector('head title').innerHTML = html.querySelector('head title').innerHTML;

            HTMLUpdateUtility.viewTransition(
              document.querySelector('main'),
              html.querySelector('main'),
              this.preProcessHtmlCallbacks,
              this.postProcessHtmlCallbacks
            );
          } else {
            HTMLUpdateUtility.viewTransition(
              this,
              html.querySelector('product-info'),
              this.preProcessHtmlCallbacks,
              this.postProcessHtmlCallbacks
            );
          }
        };
      }

      renderProductInfo({ requestUrl, targetId, callback }) {
        this.abortController?.abort();
        this.abortController = new AbortController();

        fetch(requestUrl, { signal: this.abortController.signal })
          .then((response) => response.text())
          .then((responseText) => {
            this.pendingRequestUrl = null;
            const html = new DOMParser().parseFromString(responseText, 'text/html');
            callback(html);
            // set focus to last clicked option value
            document.querySelector(`#${targetId}`)?.focus();
          })
          .catch((error) => {
            if (error.name === 'AbortError') {
              console.log('Fetch aborted by user');
            } else {
              console.error(error);
            }
            this.variantSelectors?.rejectPendingSelectPromise(error);
          });
      }

      parseJsonScript(parent, selector) {
        try {
          return JSON.parse(parent?.querySelector(selector)?.textContent);
        } catch {
          return null;
        }
      }

      getVariantSelects(queryRoot) {
        return queryRoot?.querySelector('variant-selects');
      }

      getSelectedVariant(productInfoNode) {
        return this.parseJsonScript(this.getVariantSelects(productInfoNode), '[data-selected-variant]');
      }

      buildRequestUrlWithParams(url, optionValues, shouldFetchFullPage = false) {
        const params = [];

        !shouldFetchFullPage && params.push(`section_id=${this.sectionId}`);

        if (optionValues.length) {
          params.push(`option_values=${optionValues.join(',')}`);
        }

        return `${url}?${params.join('&')}`;
      }

      updateOptionValues(html) {
        const variantSelects = html.querySelector('variant-selects');
        if (variantSelects) {
          HTMLUpdateUtility.viewTransition(this.variantSelectors, variantSelects, this.preProcessHtmlCallbacks);
        }
      }

      handleUpdateProductInfo(productUrl) {
        return (html) => {
          const sourceVariantSelects = this.getVariantSelects(html);
          const variant = this.getSelectedVariant(html);

          // Resolve product:select promise before updateOptionValues replaces the variant-selects DOM element
          this.variantSelectors?.resolvePendingSelectPromise(variant, sourceVariantSelects);

          this.pickupAvailability?.update(variant);
          this.updateOptionValues(html);
          this.updateURL(productUrl, variant?.id);
          this.updateVariantInputs(variant?.id);

          if (!variant) {
            this.setUnavailable();
            return;
          }

          this.updateMedia(html, variant?.featured_media?.id);

          const updateSourceFromDestination = (id, shouldHide = (source) => false) => {
            const source = html.getElementById(`${id}-${this.sectionId}`);
            const destination = this.querySelector(`#${id}-${this.dataset.section}`);
            if (source && destination) {
              destination.innerHTML = source.innerHTML;
              destination.classList.toggle('hidden', shouldHide(source));
            }
          };

          updateSourceFromDestination('price');
          updateSourceFromDestination('Sku', ({ classList }) => classList.contains('hidden'));
          updateSourceFromDestination('Inventory', ({ innerText }) => innerText === '');
          updateSourceFromDestination('Volume');
          updateSourceFromDestination('Price-Per-Item', ({ classList }) => classList.contains('hidden'));

          this.updateQuantityRules(this.sectionId, html);
          this.querySelector(`#Quantity-Rules-${this.dataset.section}`)?.classList.remove('hidden');
          this.querySelector(`#Volume-Note-${this.dataset.section}`)?.classList.remove('hidden');

          this.productForm?.toggleSubmitButton(
            html.getElementById(`ProductSubmitButton-${this.sectionId}`)?.hasAttribute('disabled') ?? true,
            window.variantStrings.soldOut
          );

          publish(PUB_SUB_EVENTS.variantChange, {
            data: {
              sectionId: this.sectionId,
              html,
              variant,
            },
          });
        };
      }

      updateVariantInputs(variantId) {
        this.querySelectorAll(
          `#product-form-${this.dataset.section}, #product-form-installment-${this.dataset.section}`
        ).forEach((productForm) => {
          const input = productForm.querySelector('input[name="id"]');
          input.value = variantId ?? '';
          input.dispatchEvent(new Event('change', { bubbles: true }));
        });
      }

      updateURL(url, variantId) {
        this.querySelector('share-button')?.updateUrl(
          `${window.shopUrl}${url}${variantId ? `?variant=${variantId}` : ''}`
        );

        if (this.dataset.updateUrl === 'false') return;
        window.history.replaceState({}, '', `${url}${variantId ? `?variant=${variantId}` : ''}`);
      }

      setUnavailable() {
        this.productForm?.toggleSubmitButton(true, window.variantStrings.unavailable);

        const selectors = ['price', 'Inventory', 'Sku', 'Price-Per-Item', 'Volume-Note', 'Volume', 'Quantity-Rules']
          .map((id) => `#${id}-${this.dataset.section}`)
          .join(', ');
        document.querySelectorAll(selectors).forEach(({ classList }) => classList.add('hidden'));
      }

      updateMedia(html, variantFeaturedMediaId) {
        if (!variantFeaturedMediaId) return;

        const mediaGallerySource = this.querySelector('media-gallery ul');
        const mediaGalleryDestination = html.querySelector(`media-gallery ul`);

        const refreshSourceData = () => {
          if (this.hasAttribute('data-zoom-on-hover')) enableZoomOnHover(2);
          const mediaGallerySourceItems = Array.from(mediaGallerySource.querySelectorAll('li[data-media-id]'));
          const sourceSet = new Set(mediaGallerySourceItems.map((item) => item.dataset.mediaId));
          const sourceMap = new Map(
            mediaGallerySourceItems.map((item, index) => [item.dataset.mediaId, { item, index }])
          );
          return [mediaGallerySourceItems, sourceSet, sourceMap];
        };

        if (mediaGallerySource && mediaGalleryDestination) {
          let [mediaGallerySourceItems, sourceSet, sourceMap] = refreshSourceData();
          const mediaGalleryDestinationItems = Array.from(
            mediaGalleryDestination.querySelectorAll('li[data-media-id]')
          );
          const destinationSet = new Set(mediaGalleryDestinationItems.map(({ dataset }) => dataset.mediaId));
          let shouldRefresh = false;

          // add items from new data not present in DOM
          for (let i = mediaGalleryDestinationItems.length - 1; i >= 0; i--) {
            if (!sourceSet.has(mediaGalleryDestinationItems[i].dataset.mediaId)) {
              mediaGallerySource.prepend(mediaGalleryDestinationItems[i]);
              shouldRefresh = true;
            }
          }

          // remove items from DOM not present in new data
          for (let i = 0; i < mediaGallerySourceItems.length; i++) {
            if (!destinationSet.has(mediaGallerySourceItems[i].dataset.mediaId)) {
              mediaGallerySourceItems[i].remove();
              shouldRefresh = true;
            }
          }

          // refresh
          if (shouldRefresh) [mediaGallerySourceItems, sourceSet, sourceMap] = refreshSourceData();

          // if media galleries don't match, sort to match new data order
          mediaGalleryDestinationItems.forEach((destinationItem, destinationIndex) => {
            const sourceData = sourceMap.get(destinationItem.dataset.mediaId);

            if (sourceData && sourceData.index !== destinationIndex) {
              mediaGallerySource.insertBefore(
                sourceData.item,
                mediaGallerySource.querySelector(`li:nth-of-type(${destinationIndex + 1})`)
              );

              // refresh source now that it has been modified
              [mediaGallerySourceItems, sourceSet, sourceMap] = refreshSourceData();
            }
          });
        }

        // set featured media as active in the media gallery
        this.querySelector(`media-gallery`)?.setActiveMedia?.(
          `${this.dataset.section}-${variantFeaturedMediaId}`,
          true
        );

        // update media modal
        const modalContent = this.productModal?.querySelector(`.product-media-modal__content`);
        const newModalContent = html.querySelector(`product-modal .product-media-modal__content`);
        if (modalContent && newModalContent) modalContent.innerHTML = newModalContent.innerHTML;
      }

      setQuantityBoundries() {
        const data = {
          cartQuantity: this.quantityInput.dataset.cartQuantity ? parseInt(this.quantityInput.dataset.cartQuantity) : 0,
          min: this.quantityInput.dataset.min ? parseInt(this.quantityInput.dataset.min) : 1,
          max: this.quantityInput.dataset.max ? parseInt(this.quantityInput.dataset.max) : null,
          step: this.quantityInput.step ? parseInt(this.quantityInput.step) : 1,
        };

        let min = data.min;
        const max = data.max === null ? data.max : data.max - data.cartQuantity;
        if (max !== null) min = Math.min(min, max);
        if (data.cartQuantity >= data.min) min = Math.min(min, data.step);

        this.quantityInput.min = min;

        if (max) {
          this.quantityInput.max = max;
        } else {
          this.quantityInput.removeAttribute('max');
        }
        this.quantityInput.value = min;

        publish(PUB_SUB_EVENTS.quantityUpdate, undefined);
      }

      fetchQuantityRules() {
        const currentVariantId = this.productForm?.variantIdInput?.value;
        if (!currentVariantId) return;

        this.querySelector('.quantity__rules-cart .loading__spinner').classList.remove('hidden');
        return fetch(`${this.dataset.url}?variant=${currentVariantId}&section_id=${this.dataset.section}`)
          .then((response) => response.text())
          .then((responseText) => {
            const html = new DOMParser().parseFromString(responseText, 'text/html');
            this.updateQuantityRules(this.dataset.section, html);
          })
          .catch((e) => console.error(e))
          .finally(() => this.querySelector('.quantity__rules-cart .loading__spinner').classList.add('hidden'));
      }

      updateQuantityRules(sectionId, html) {
        if (!this.quantityInput) return;
        this.setQuantityBoundries();

        const quantityFormUpdated = html.getElementById(`Quantity-Form-${sectionId}`);
        const selectors = ['.quantity__input', '.quantity__rules', '.quantity__label'];
        for (let selector of selectors) {
          const current = this.quantityForm.querySelector(selector);
          const updated = quantityFormUpdated.querySelector(selector);
          if (!current || !updated) continue;
          if (selector === '.quantity__input') {
            const attributes = ['data-cart-quantity', 'data-min', 'data-max', 'step'];
            for (let attribute of attributes) {
              const valueUpdated = updated.getAttribute(attribute);
              if (valueUpdated !== null) {
                current.setAttribute(attribute, valueUpdated);
              } else {
                current.removeAttribute(attribute);
              }
            }
          } else {
            current.innerHTML = updated.innerHTML;
            if (selector === '.quantity__label') {
              const updatedAriaLabelledBy = updated.getAttribute('aria-labelledby');
              if (updatedAriaLabelledBy) {
                current.setAttribute('aria-labelledby', updatedAriaLabelledBy);
                // Update the referenced visually hidden element
                const labelId = updatedAriaLabelledBy;
                const currentHiddenLabel = document.getElementById(labelId);
                const updatedHiddenLabel = html.getElementById(labelId);
                if (currentHiddenLabel && updatedHiddenLabel) {
                  currentHiddenLabel.textContent = updatedHiddenLabel.textContent;
                }
              }
            }
          }
        }
      }

      get productForm() {
        return this.querySelector(`product-form`);
      }

      get productModal() {
        return document.querySelector(`#ProductModal-${this.dataset.section}`);
      }

      get pickupAvailability() {
        return this.querySelector(`pickup-availability`);
      }

      get variantSelectors() {
        return this.querySelector('variant-selects');
      }

      get relatedProducts() {
        const relatedProductsSectionId = SectionId.getIdForSection(
          SectionId.parseId(this.sectionId),
          'related-products'
        );
        return document.querySelector(`product-recommendations[data-section-id^="${relatedProductsSectionId}"]`);
      }

      get quickOrderList() {
        const quickOrderListSectionId = SectionId.getIdForSection(
          SectionId.parseId(this.sectionId),
          'quick_order_list'
        );
        return document.querySelector(`quick-order-list[data-id^="${quickOrderListSectionId}"]`);
      }

      get sectionId() {
        return this.dataset.originalSection || this.dataset.section;
      }
    }
  );
}

/*
 * Rhino Lapidary brand and interface foundation.
 *
 * Rules:
 * - Keep Rhino-specific styling here or in future assets/rhino-*.css files.
 * - Prefer --rhino-* custom properties.
 * - Do not edit inherited Trade CSS for Rhino-specific visual changes unless documented.
 *
 * Source PBIs:
 * - B-005 Accessible color system
 * - B-006 Typography and technical hierarchy
 * - B-007 Layout, spacing, and surfaces
 * - B-008 Buttons, links, and CTA hierarchy
 * - B-009 Forms and storefront states
 *
 * Architecture:
 * - Keep Rhino-owned selectors prefixed with `.rhino-`.
 * - Keep Rhino-owned customer properties prefixed with `--rhino-`.
 * - Do not reproduce Trade component CSS in this file.
 * - Apply component classes intentionally during preview implementation.
 */

.rhino-machine-shell .product--no-media .product__info-wrapper {
    min-width: 0;
    width: 100%;
}

.rhino-machine-shell .product__title,
.rhino-machine-shell .price,
.rhino-machine-shell .form__label,
.rhino-machine-shell .product-form__input label,
.rhino-machine-shell .button {
    overflow-wrap: anywhere;
    white-space: normal;
}

.rhino-machine-shell .product-form__input,
.rhino-machine-shell .product-form__buttons,
.rhino-machine-shell .price__container {
    min-width: 0;
    max-width: 100%;
}

.rhino-machine-shell .product-form__input input[type='radio'] + label {
    max-width: 100%;
}

.rhino-machine-shell .button {
    height: auto;
    padding-block: var(--rhino-space-3);
}

.rhino-machine-shell .rhino-machine-contact {
    display: flex;
    width: fit-content;
    max-width: 100%;
    margin-inline: auto;
}

:root {
    /* Code brand colors */
    --rhino-color-red-500: #ed1c24;
    --rhino-color-red-700: #b51820;
    --rhino-color-red-900: #791716;
    --rhino-color-gold-500: #b6830d;
    --rhino-color-black: #000000;
    --rhino-color-white: #ffffff;

    /* Neutral interface colors */
    --rhino-color-carbon: #111111;
    --rhino-color-graphite: #2b2d30;
    --rhino-color-steel: #5d6670;
    --rhino-color-alloy: #c9cdd2;
    --rhino-color-mist: #f3f4f5;
    --rhino-color-warm-white: #fcfbf8;

    /* Functional colors */
    --rhino-color-link: #a3151c;
    --rhino-color-info: #0b5ea8;
    --rhino-color-success: #1f6b45;
    --rhino-color-warning: #7a4a00;
    --rhino-color-error: #b42318;

    /* Functional surfaces */
    --rhino-color-info-surface: #eef6fc;
    --rhino-color-success-surface: #eef8f2;
    --rhino-color-warning-surface: #fff7e8;
    --rhino-color-error-surface: #fff1f0;

    /* Semantic color aliases */
    --rhino-color-brand-primary: var(--rhino-color-red-500);
    --rhino-color-action: var(--rhino-color-red-700);
    --rhino-color-action-hover: var(--rhino-color-red-900);
    --rhino-color-focus: var(--rhino-color-red-500);
    --rhino-color-surface: var(--rhino-color-white);
    --rhino-color-surface-alternate: var(--rhino-color-mist);
    --rhino-color-surface-editorial: var(--rhino-color-warm-white);
    --rhino-color-surface-dark: var(--rhino-color-carbon);
    --rhino-color-text: var(--rhino-color-carbon);
    --rhino-color-text-muted: var(--rhino-color-steel);
    --rhino-color-border: var(--rhino-color-alloy);
    --rhino-color-border-strong: var(--rhino-color-graphite);
    --rhino-color-focus-shadow: rgba(237, 28, 36, 0.2);
    --rhino-color-overlay-dark: rgba(17, 17, 17, 0.88);

    /* Font family and weight */
    --rhino-font-family-sans:
        "DM Sans",
        var(--font-heading-family),
        Arial,
        sans-serif;
    --rhino-font-weight-regular: 400;
    --rhino-font-weight-medium: 500;
    --rhino-font-weight-semibold: 600;
    --rhino-font-weight-bold: 700;

    /* General type scale */
    --rhino-font-size-xs: 1.2rem;
    --rhino-font-size-sm: 1.3rem;
    --rhino-font-size-compact: 1.4rem;
    --rhino-font-size-button: 1.5rem;
    --rhino-font-size-body: 1.6rem;
    --rhino-font-size-lg: 1.8rem;
    --rhino-font-size-xl: 2rem;
    --rhino-font-size-2xl: 2.4rem;
    --rhino-font-size-3xl: 2.8rem;
    --rhino-font-size-4xl: 3.2rem;
    --rhino-font-size-5xl: 4rem;

    /* Semantic type roles */
    --rhino-type-page-title-size: var(--rhino-font-size-4xl);
    --rhino-type-page-title-line-height: 1.25;
    --rhino-type-product-title-size: var(--rhino-font-size-3xl);
    --rhino-type-product-title-line-height: 1.285;
    --rhino-type-section-title-size: var(--rhino-font-size-2xl);
    --rhino-type-section-title-line-height: 1.333;
    --rhino-type-subsection-title-size: var(--rhino-font-size-xl);
    --rhino-type-subsection-title-line-height: 1.4;
    --rhino-type-body-line-height: 1.625;
    --rhino-type-compact-line-height: 1.571;
    --rhino-type-label-letter-spacing: 0.08em;

    /* Spacing scale */
    --rhino-space-1: 0.4rem;
    --rhino-space-2: 0.8rem;
    --rhino-space-3: 1.2rem;
    --rhino-space-4: 1.6rem;
    --rhino-space-5: 2.4rem;
    --rhino-space-6: 3.2rem;
    --rhino-space-7: 4.8rem;
    --rhino-space-8: 6.4rem;
    --rhino-space-9: 9.6rem;

    /* Width and gutters */
    --rhino-width-canvas: 140rem;
    --rhino-width-content: 112rem;
    --rhino-width-prose: 72rem;
    --rhino-width-form: 64rem;
    --rhino-page-gutter: var(--rhino-space-4);

    /* Section rhythm */
    --rhino-section-spacing-y: 4rem;
    --rhino-section-spacing-dense-y: var(--rhino-space-5);
    --rhino-section-spacing-major-y: var(--rhino-space-8);

    /* Borders */
    --rhino-border-width: 0.1rem;
    --rhino-border-width-accent: 0.4rem;
    --rhino-border-standard:
        var(--rhino-border-width)
        solid
        var(--rhino-color-border);
    --rhino-border-strong:
        var(--rhino-border-width)
        solid
        var(--rhino-color-border-strong);

    /* Radii */
    --rhino-radius-control: 0.4rem;
    --rhino-radius-panel: 0.4rem;
    --rhino-radius-media: 0.6rem;
    --rhino-radius-overlay: 0.6rem;
    --rhino-radius-round: 50%;

    /* Control sizing */
    --rhino-control-min-height: 4.4rem;
    --rhino-control-comfortable-height: 4.8rem;
    --rhino-icon-button-size: 4.4rem;

    /* Focus */
    --rhino-focus-width: 0.3rem;
    --rhino-focus-offset: 0.2rem;
    --rhino-focus-ring:
        var(--rhino-focus-width)
        solid
        var(--rhino-color-focus);

    /* Overlay elevation only */
    --rhino-shadow-overlay:
        0 1.6rem 4rem rgba(17, 17, 17, 0.18);
    --rhino-shadow-drawer:
        0 0 3.2rem rgba(17, 17, 17, 0.2);

    /* Motion */
    --rhino-motion-duration-instant: 80ms;
    --rhino-motion-duration-fast: 160ms;
    --rhino-motion-duration-standard: 240ms;
    --rhino-motion-easing-standard: cubic-bezier(0.2, 0, 0, 1);
    --rhino-motion-easing-exit: cubic-bezier(0.4, 0, 1, 1);
    --rhino-motion-distance: 0.8rem;
}

@media screen and (min-width: 750px) {
    :root {
        --rhino-page-gutter: var(--rhino-space-5);
        --rhino-section-spacing-y: var(--rhino-space-8);
        --rhino-section-spacing-dense-y: var(--rhino-space-6);
        --rhino-section-spacing-major-y: var(--rhino-space-9);
        --rhino-type-page-title-size: var(--rhino-font-size-5xl);
        --rhino-type-product-title-size: var(--rhino-font-size-4xl);
        --rhino-type-section-title-size: var(--rhino-font-size-3xl);
        --rhino-type-subsection-title-size: 2.2rem;
    }
}

@media screen and (min-width: 990px) {
    :root {
        --rhino-page-gutter: var(--rhino-space-6);
    }
}

/* --------------------------------------------------------------------------
 * Global foundation
 * -------------------------------------------------------------------------- */
body {
    color: var(--rhino-color-text);
    font-family: var(--rhino-font-family-sans);
    font-size: var(--rhino-font-size-body);
    font-variant-numeric: lining-nums;
    line-height: var(--rhino-type-body-line-height);
}

h1,
h2,
h3,
h4,
h5,
h6,
.button,
button,
input,
select,
textarea {
    font-family: var(--rhino-font-family-sans);
}

h1,
h2,
h3,
h4,
h5,
h6 {
    color: inherit;
    font-weight: var(--rhino-font-weight-bold);
    overflow-wrap: anywhere;
    text-wrap: balance;
}

p,
li,
dd {
    overflow-wrap: break-word;
    text-wrap: pretty;
}

:where(
    a,
    button,
    input,
    select,
    textarea,
    summary,
    [tabindex]:not([tabindex="-1"])
):focus-visible {
    outline: var(--rhino-focus-ring);
    outline-offset: var(--rhino-focus-offset);
}

::selection {
    background: var(--rhino-color-red-900);
    color: var(--rhino-color-white);
}

/* --------------------------------------------------------------------------
 * Typography roles
 * -------------------------------------------------------------------------- */

.rhino-page-title {
    font-size: var(--rhino-type-page-title-size);
    font-weight: var(--rhino-font-weight-bold);
    letter-spacing: -0.02em;
    line-height: var(--rhino-type-page-title-line-height);
    margin-block: 0;
}

.rhino-product-title {
    font-size: var(--rhino-type-product-title-size);
    font-weight: var(--rhino-font-weight-bold);
    letter-spacing: -0.015em;
    line-height: var(--rhino-type-product-title-line-height);
    margin-block: 0;
    overflow-wrap: anywhere;
}

.rhino-section-title {
    font-size: var(--rhino-type-section-title-size);
    font-weight: var(--rhino-font-weight-bold);
    line-height: var(--rhino-type-section-title-line-height);
    margin-block: 0;
}

.rhino-subsection-title {
    font-size: var(--rhino-type-subsection-title-size);
    font-weight: var(--rhino-font-weight-semibold);
    line-height: var(--rhino-type-subsection-title-line-height);
    margin-block: 0;
}

.rhino-product-subtitle {
    color: var(--rhino-color-text-muted);
    font-size: var(--rhino-font-size-lg);
    font-weight: var(--rhino-font-weight-medium);
    line-height: 1.555;
    margin-block: 0;
}

.rhino-technical-label,
.rhino-eyebrow {
    color: var(--rhino-color-text-muted);
    font-size: var(--rhino-font-size-xs);
    font-weight: var(--rhino-font-weight-semibold);
    letter-spacing: var(--rhino-type-label-letter-spacing);
    line-height: 1.5;
    text-transform: uppercase;
}

.rhino-spec-value {
    color: var(--rhino-color-text);
    font-size: var(--rhino-font-size-body);
    font-variant-numeric: tabular-nums lining-nums;
    font-weight: var(--rhino-font-weight-semibold);
    line-height: 1.5;
}

.rhino-price {
    color: var(--rhino-color-text);
    font-size: 2.6rem;
    font-variant-numeric: tabular-nums lining-nums;
    font-weight: var(--rhino-font-weight-bold);
    line-height: 1.307;
}

.rhino-caption {
    color: var(--rhino-color-text-muted);
    font-size: var(--rhino-font-size-sm);
    line-height: 1.538;
}

.rhino-prose {
    font-size: var(--rhino-font-size-body);
    line-height: var(--rhino-type-body-line-height);
    max-width: var(--rhino-width-prose);
}

.rhino-prose > *:first-child {
    margin-block-start: 0;
}

.rhino-prose > *:last-child {
    margin-block-end: 0;
}

.rhino-nowrap {
    white-space: nowrap;
}

/* --------------------------------------------------------------------------
 * Layout primitives
 * ------------------------------------------------------------------------- */

.rhino-container,
.rhino-container--wide,
.rhino-container--prose,
.rhino-container--form {
    margin-inline: auto;
    width: calc(100% - (var(--rhino-page-gutter) * 2));
}

.rhino-container {
    max-width: var(--rhino-width-content);
}

.rhino-container--wide {
    max-width: var(--rhino-width-canvas);
}

.rhino-container--prose {
    max-width: var(--rhino-width-prose);
}

.rhino-container--form {
    max-width: var(--rhino-width-form);
}

.rhino-section {
    padding-block: var(--rhino-section-spacing-y);
}

.rhino-section--dense {
    padding-block: var(--rhino-section-spacing-dense-y);
}

.rhino-section--major {
    padding-block: var(--rhino-section-spacing-major-y);
}

.rhino-stack {
    --rhino-stack-gap: var(--rhino-space-4);

    display: flex;
    flex-direction: column;
}

.rhino-stack > * {
    margin-block: 0;
}

.rhino-stack > * + * {
    margin-block-start: var(--rhino-stack-gap);
}

.rhino-stack--compact {
    --rhino-stack-gap: var(--rhino-space-2);
}

.rhino-stack--technical {
    --rhino-stack-gap: var(--rhino-space-3);
}

.rhino-stack--spacious {
    --rhino-stack-gap: var(--rhino-space-6);
}

.rhino-cluster {
    --rhino-cluster-gap: var(--rhino-space-3);

    align-items: center;
    display: flex;
    flex-wrap: wrap;
    gap: var(--rhino-cluster-gap);
}

.rhino-grid {
    --rhino-grid-min: 24rem;
    --rhino-grid-gap: var(--rhino-space-5);

    display: grid;
    gap: var(--rhino-grid-gap);
    grid-template-columns:
        repeat(
            auto-fit,
            minmax(min(100%, var(--rhino-grid-min)), 1fr)
        );
}

.rhino-divider {
    border: 0;
    border-block-start: var(--rhino-border-standard);
    margin-block: var(--rhino-space-5);
}

/* ---------------------------------------------------------------------------
 * Surfaces and panels
 * ------------------------------------------------------------------------- */

.rhino-panel {
    background: var(--rhino-color-surface);
    border: var(--rhino-border-standard);
    border-radius: var(--rhino-radius-panel);
    color: var(--rhino-color-text);
    padding: var(--rhino-space-5);
}

.rhino-panel--alternate {
    background: var(--rhino-color-surface-alternate);
}

.rhino-panel--editorial {
    background: var(--rhino-color-surface-editorial);
}

.rhino-panel--strong {
    border-color: var(--rhino-color-border-strong);
}

.rhino-panel--accent {
    border-inline-start:
        var(--rhino-border-width-accent)
        solid
        var(--rhino-color-red-700);
}

.rhino-panel--dark {
    background: var(--rhino-color-surface-dark);
    border-color: var(--rhino-color-graphite);
    color: var(--rhino-color-white);
}

.rhino-media-frame {
    background: var(--rhino-color-surface-alternate);
    border: var(--rhino-border-standard);
    border-radius: var(--rhino-radius-media);
    overflow: hidden;
}

/* ---------------------------------------------------------------------------
 * Links
 * ------------------------------------------------------------------------- */

.rhino-link {
    color: var(--rhino-color-link);
    font-weight: var(--rhino-font-weight-medium);
    text-decoration-line: underline;
    text-decoration-thickness: 0.1em;
    text-underline-offset: 0.18em;
}

.rhino-link:hover {
    color: var(--rhino-color-red-900);
    text-decoration-thickness: 0.14em;
}

.rhino-link--muted {
    color: var(--rhino-color-text-muted);
}

.rhino-link--muted:hover {
    color: var(--rhino-color-text);
}

/* -------------------------------------------------------------------------
 * Buttons and action groups
 * ------------------------------------------------------------------------- */

.rhino-button {
    align-items: center;
    appearance: none;
    background: transparent;
    border: var(--rhino-border-width) solid transparent;
    border-radius: var(--rhino-radius-control);
    box-shadow: none;
    color: inherit;
    cursor: pointer;
    display: inline-flex;
    font-size: var(--rhino-font-size-button);
    font-weight: var(--rhino-font-weight-semibold);
    gap: var(--rhino-space-2);
    justify-content: center;
    line-height: 1.333;
    min-height: var(--rhino-control-min-height);
    padding: var(--rhino-space-3) var(--rhino-space-5);
    text-align: center;
    text-decoration: none;
}

.rhino-button--primary {
    background: var(--rhino-color-action);
    border-color: var(--rhino-color-action);
    color: var(--rhino-color-white);
}

.rhino-button--primary:hover {
    background: var(--rhino-color-action-hover);
    border-color: var(--rhino-color-action-hover);
    color: var(--rhino-color-white);
}

.rhino-button--secondary {
    background: var(--rhino-color-white);
    border-color: var(--rhino-color-border-strong);
    color: var(--rhino-color-carbon);
}

.rhino-button--secondary:hover {
    background: var(--rhino-color-mist);
}

.rhino-button--tertiary {
    border-color: transparent;
    color: var(--rhino-color-link);
    padding-inline: var(--rhino-space-2);
    text-decoration-line: underline;
    text-decoration-thickness: 0.1em;
    text-underline-offset: 0.18em;
}

.rhino-button--tertiary:hover {
    color: var(--rhino-color-red-900);
    text-decoration-thickness: 0.14em;
}

.rhino-button--support {
    background: var(--rhino-color-info-surface);
    border-color: var(--rhino-color-info);
    color: var(--rhino-color-info);
}

.rhino-button--support:hover {
    background: var(--rhino-color-info);
    color: var(--rhino-color-white);
}

.rhino-button--danger {
    background: var(--rhino-color-white);
    border-color: var(--rhino-color-error);
    color: var(--rhino-color-error);
}

.rhino-button--danger:hover {
    background: var(--rhino-color-error);
    color: var(--rhino-color-white);
}

.rhino-button--icon {
    min-width: var(--rhino-icon-button-size);
    padding: var(--rhino-space-2);
    width: var(--rhino-icon-button-size);
}

.rhino-button:is(
    :disabled,
    [disabled],
    [aria-disabled="true"]
) {
    cursor: not-allowed;
    opacity: 0.55;
}

.rhino-button[aria-busy="true"],
.rhino-button.is-loading {
    cursor: progress;
}

.rhino-action-group {
    align-items: center;
    display: flex;
    flex-wrap: wrap;
    gap: var(--rhino-space-3);
}

@media screen and (max-width: 749px) {
    .rhino-action-group--stack-mobile {
        align-items: stretch;
        flex-direction: column;
    }

    .rhino-action-group--stack-mobile .rhino-button {
        width: 100%;
    }
}

/* --------------------------------------------------------------------------
 * Forms
 * ------------------------------------------------------------------------- */

.rhino-form {
    max-width: var(--rhino-width-form);
}

.rhino-field {
    display: flex;
    flex-direction: column;
    gap: var(--rhino-space-2);
}

.rhino-field + .rhino-field {
    margin-block-start: var(--rhino-space-5);
}

.rhino-field__label {
    color: var(--rhino-color-text);
    font-size: var(--rhino-font-size-compact);
    font-weight: var(--rhino-font-weight-semibold);
    line-height: var(--rhino-type-compact-line-height);
}

.rhino-field__requirement {
    color: var(--rhino-color-text-muted);
    font-weight: var(--rhino-font-weight-regular);
}

.rhino-field__hint {
    color: var(--rhino-color-text-muted);
    font-size: var(--rhino-font-size-sm);
    line-height: 1.538;
}

.rhino-field__control {
    background: var(--rhino-color-white);
    border: var(--rhino-border-standard);
    border-radius: var(--rhino-radius-control);
    color: var(--rhino-color-text);
    font: inherit;
    min-height: var(--rhino-control-comfortable-height);
    padding: var(--rhino-space-3) var(--rhino-space-4);
    width: 100%;
}

textarea.rhino-field__control {
    min-height: 14rem;
    resize: vertical;
}

.rhino-field__control:hover {
    border-color: var(--rhino-color-steel);
}

.rhino-field__control:focus-visible {
    border-color: var(--rhino-color-focus);
    box-shadow:
        0 0 0
        var(--rhino-focus-width)
        var(--rhino-color-focus-shadow);
    outline: none;
}

.rhino-field__control[aria-invalid="true"] {
    border-color: var(--rhino-color-error);
}

.rhino-field__control:disabled {
    background: var(--rhino-color-mist);
    color: var(--rhino-color-text-muted);
    cursor: not-allowed;
}

.rhino-field__message {
    color: var(--rhino-color-text-muted);
    font-size: var(--rhino-font-size-sm);
    line-height: 1.538;
}

.rhino-field__message--error {
    color: var(--rhino-color-error);
    font-weight: var(--rhino-font-weight-medium);
}

.rhino-field__message--success {
    color: var(--rhino-color-success);
    font-weight: var(--rhino-font-weight-medium);
}

.rhino-form-actions {
    align-items: center;
    display: flex;
    flex-wrap: wrap;
    gap: var(--rhino-space-3);
    margin-block-start: var(--rhino-space-6);
}

/* ---------------------------------------------------------------------------
 * Storefront states
 * ------------------------------------------------------------------------- */

.rhino-state {
    --rhino-state-accent: var(--rhino-color-info);
    --rhino-state-background: var(--rhino-color-info-surface);

    background: var(--rhino-state-background);
    border: var(--rhino-border-standard);
    border-inline-start:
        var(--rhino-border-width-accent)
        solid
        var(--rhino-state-accent);
    border-radius: var(--rhino-radius-panel);
    color: var(--rhino-color-text);
    padding: var(--rhino-space-4);
}

.rhino-state__title {
    color: inherit;
    font-size: var(--rhino-font-size-body);
    font-weight: var(--rhino-font-weight-semibold);
    line-height: 1.5;
    margin: 0;
}

.rhino-state__message {
    margin-block:
        var(--rhino-space-2)
        0;
}

.rhino-state--success {
    --rhino-state-accent: var(--rhino-color-success);
    --rhino-state-background: var(--rhino-color-success-surface);
}

.rhino-state--warning {
    --rhino-state-accent: var(--rhino-color-warning);
    --rhino-state-background: var(--rhino-color-warning-surface);
}

.rhino-state--error {
    --rhino-state-accent: var(--rhino-color-error);
    --rhino-state-background: var(--rhino-color-error-surface);
}

.rhino-state--neutral,
.rhino-empty-state {
    --rhino-state-accent: var(--rhino-color-steel);
    --rhino-state-background: var(--rhino-color-mist);
}

.rhino-empty-state {
    background: var(--rhino-color-mist);
    border: var(--rhino-border-standard);
    border-radius: var(--rhino-radius-panel);
    padding: var(--rhino-space-7) var(--rhino-space-5);
    text-align: center;
}

.rhino-empty-state > * {
    margin-inline: auto;
    max-width: var(--rhino-width-form);
}

/* ---------------------------------------------------------------------------
 * Specification tables
 * ------------------------------------------------------------------------- */

.rhino-spec-table-wrapper {
    max-width: 100%;
    overflow-x: auto;
}

.rhino-spec-table {
    border-collapse: collapse;
    color: var(--rhino-color-text);
    font-variant-numeric: tabular-nums lining-nums;
    width: 100%;
}

.rhino-spec-table th,
.rhino-spec-table td {
    border-block-end: var(--rhino-border-standard);
    padding:
        var(--rhino-space-3)
        var(--rhino-space-4);
    text-align: start;
    vertical-align: top;
}

.rhino-spec-tabl th {
    color: var(--rhino-color-text-muted);
    font-size: var(--rhino-font-size-xs);
    font-weight: var(--rhino-font-weight-semibold);
    letter-spacing: var(--rhino-type-label-letter-spacing);
    text-transform: uppercase;
}

.rhino-spec-table tbody th {
    color: var(--rhino-color-text);
    font-size: var(--rhino-font-size-compact);
    letter-spacing: 0;
    text-transform: none;
}

.rhino-spec-table tbody tr:hover {
    background: var(--rhino-color-mist);
}

/* ---------------------------------------------------------------------------
 * Accessibility preferences
 * ------------------------------------------------------------------------- */

@media (forced-colors: active) {
    .rhino-button,
    .rhino-field__control,
    .rhino-panel,
    .rhino-panel,
    .rhino-empty-state {
        forced-color-adjust: auto;
    }

    :where(
        a,
        button,
        input,
        select,
        textarea,
        summary,
        [tabindex]:not([tabindex="-1"])
    ):focus-visible {
        outline-color: Highlight;
    }
}

@media (prefers-reduced-motion: reduce) {
    .rhino-button,
    .rhino-link,
    .rhino-field__control {
        scroll-behavior: auto;
        transition-duration: 0.01ms;
    }
}

/* --------------------------------------------------------------------------
 * Product badges and trust markers
 * Source PBIs: B-010, B-012, B-023
 * -------------------------------------------------------------------------- */

.rhino-badge-list {
    align-items: center;
    display: flex;
    flex-wrap: wrap;
    gap: var(--rhino-space-2);
    list-style: none;
    margin: 0;
    padding: 0;
}

.rhino-badge {
    align-items: center;
    background: var(--rhino-color-white);
    border: var(--rhino-border-standard);
    border-radius: var(--rhino-radius-control);
    color: var(--rhino-color-graphite);
    display: inline-flex;
    font-size: var(--rhino-font-size-xs);
    font-weight: var(--rhino-font-weight-semibold);
    gap: var(--rhino-space-1);
    letter-spacing: 0.02em;
    line-height: 1.333;
    min-height: 2.8rem;
    padding: var(--rhino-space-1) var(--rhino-space-2);
    text-transform: none;
}

.rhino-badge .rhino-icon {
    flex: 0 0 auto;
    height: 1.6rem;
    width: 1.6rem;
}

.rhino-badge--product-class {
    background: var(--rhino-color-mist);
    color: var(--rhino-color-carbon);
}

.rhino-badge--availability {
    border-color: var(--rhino-color-error);
    color: var(--rhino-color-error);
}

.rhino-badge--warning {
    background: var(--rhino-color-warning-surface);
    border-color: var(--rhino-color-warning);
    color: var(--rhino-color-warning);
}

.rhino-badge--freight {
    background: var(--rhino-color-info-surface);
    border-color: var(--rhino-color-info);
    color: var(--rhino-color-info);
}

.rhino-badge--compatibility {
    background: var(--rhino-color-success-surface);
    border-color: var(--rhino-color-success);
    color: var(--rhino-color-success);
}

.rhino-badge--sale {
    background: var(--rhino-color-red-900);
    border-color: var(--rhino-color-red-900);
    color: var(--rhino-color-white);
}

.rhino-badge--new {
    background: var(--rhino-color-white);
    border-color: var(--rhino-color-red-700);
    color: var(--rhino-color-red-700);
}

.rhino-trust-list {
    border-block:
            var(--rhino-border-standard);
    display: grid;
    margin: 0;
}

.rhino-trust-marker {
    align-items: start;
    display: grid;
    gap: var(--rhino-space-3);
    grid-template-columns: auto minmax(0, 1fr);
    padding-block: var(--rhino-space-4);
