.rhino-trust-marker + .rhino-trust-marker {
    border-block-start: var(--rhino-border-standard);
}

.rhino-trust-marker__icon {
    align-items: center;
    color: var(--rhino-color-info);
    display: inline-flex;
    height: 2.4rem;
    justify-content: center;
    width: 2.4rem;
}

.rhino-trust-marker__content {
    min-width: 0;
}

.rhino-trust-marker__title {
    color: var(--rhino-color-text);
    font-size: var(--rhino-font-size-compact);
    font-weight: var(--rhino-font-weight-semibold);
    line-height: var(--rhino-type-compact-line-height);
    margin: 0;
}

.rhino-trust-marker__text {
    color: var(--rhino-color-text-muted);
    font-size: var(--rhino-font-size-compact);
    line-height: var(--rhino-type-compact-line-height);
    margin:
            var(--rhino-space-1)
            0
            0;
}

.rhino-trust-marker__action {
    display: inline-block;
    margin-block-start: var(--rhino-space-2);
}

/* --------------------------------------------------------------------------
 * Machine family identifiers
 * Source PBI: B-012
 * -------------------------------------------------------------------------- */

.rhino-family-identifier {
    --rhino-family-accent: var(--rhino-color-red-700);

    align-items: center;
    background: var(--rhino-color-white);
