/* Progressive fragment focus only. Links, paging and native commerce work without JS. */
(() => {
  const root = document.querySelector('[data-rhino-g-catalog]');
  if (!root) return;
  const header = document.querySelector('.section-header');
  const offset = () => root.style.setProperty('--rhino-g-catalog-offset', `${Math.ceil(header?.getBoundingClientRect().height || 0) + 24}px`);
  offset();
  if (header && typeof ResizeObserver !== 'undefined') new ResizeObserver(offset).observe(header);
  root.addEventListener('focusin', event => {
    if (!event.target.matches('a[href]:focus-visible')) return;
    const top = Math.ceil(header?.getBoundingClientRect().height || 0) + 24;
    const rect = event.target.getBoundingClientRect();
    if (rect.top < top) window.scrollBy(0, rect.top - top);
  });
  const arrive = () => {
    const target = document.getElementById(location.hash.slice(1));
    if (!target || !root.contains(target) || !target.hasAttribute('tabindex')) return;
    target.focus({ preventScroll: true });
    target.scrollIntoView({ block: 'start' });
  };
  root.addEventListener('click', event => {
    const link = event.target.closest('a[href^="#"]');
    if (link && link.hash === location.hash) requestAnimationFrame(arrive);
  });
  window.addEventListener('hashchange', arrive);
  if (location.hash) requestAnimationFrame(arrive);
})();

/* Only suppresses time-expired server-approved markup. Creates no fit authority. */
if (!customElements.get('rhino-g-fit')) {
  customElements.define('rhino-g-fit', class extends HTMLElement {
    connectedCallback() {
      this.check = this.check.bind(this);
      this.check();
      window.addEventListener('pageshow', this.check);
      document.addEventListener('visibilitychange', this.check);
    }

    disconnectedCallback() {
      window.removeEventListener('pageshow', this.check);
      document.removeEventListener('visibilitychange', this.check);
      clearTimeout(this.expiryTimer);
    }

    check() {
      clearTimeout(this.expiryTimer);
      const now = Date.now();
      const from = Date.parse(this.dataset.validFrom);
      const until = Date.parse(this.dataset.expiresAt);
      const product = this.closest('product-info');
      const valid = Number.isFinite(from) && Number.isFinite(until) &&
        now >= from && now < until && product?.dataset.productId === this.dataset.productId;
      this.hidden = !valid;
      if (valid) this.expiryTimer = setTimeout(this.check, Math.min(until - now, 2147483647));
    }
  });
}

